// React is exposed on window by the panel's slot loader; components register
// into window.KS and render wherever the host mounts the declared slot.
(function () {
  var h = window.React.createElement;
  function Banner(props) {
    var text = (props && props.text) || 'Hello from UI Showcase';
    var tone = (props && props.tone) || 'info';
    var cls = tone === 'warn'
      ? 'border-amber-700/50 bg-amber-900/20 text-amber-200'
      : 'border-sky-700/50 bg-sky-900/20 text-sky-200';
    return h('div', { className: 'rounded-lg border px-3 py-2 text-sm ' + cls }, text);
  }
  window.KS.registerComponent('instance.detail.tabs', 'Banner', Banner);
})();
`}),xe=()=>({...f(),name:"Terminal Monitor",slug:"terminal-monitor",version:"0.1.0",description:"Subscribes to instance.start / instance.stop events and writes a structured log entry through the terminal capability. Demonstrates the v2 hook + backendScript flow.",engineVersion:2,permissionsRequested:[{capability:"terminal",access_level:"read_write"}],hooks:[{event:"post:instance.start",phase:"post",handler:"onInstanceStart"},{event:"post:instance.stop",phase:"post",handler:"onInstanceStop"}],backendScript:`// Terminal Monitor — registered by the Mod Studio.
// Runs inside the panel's Goja VM; logs every instance lifecycle
// event through ks.log and writes a counter to the mod's storage.
ks.events.on('post:instance.start', function (payload) {
  ks.log('info', 'instance.start fired for ' + (payload && payload.id));
  ks.storage.set('starts', String((Number(ks.storage.get('starts') || 0) + 1)));
});

ks.events.on('post:instance.stop', function (payload) {
  ks.log('info', 'instance.stop fired for ' + (payload && payload.id));
});

function onInstanceStart(payload) { ks.log('info', 'hook:start ' + (payload && payload.id)); }
function onInstanceStop(payload)  { ks.log('info', 'hook:stop '  + (payload && payload.id)); }
